http {
    upstream app_servers {
        least_conn;
        server app1.internal:3000 weight=3;
        server app2.internal:3000;
        server app3.internal:3000 backup;
    }

    server {
        listen 80;
        location / {
            proxy_pass http://app_servers;
            proxy_next_upstream error timeout http_500;
        }
    }
}
